package za.co.loopmanager;
import android.content.Context;import android.app.admin.DevicePolicyManager;import android.os.SystemClock;import android.provider.Settings;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={30,35})
public class UpdateGateTest {
 @Test public void requiredUpdateGateHasRecoveryDeadlineAndDoesNotInterruptCheckout(){Context c=RuntimeEnvironment.getApplication();Shadows.shadowOf(c.getSystemService(DevicePolicyManager.class)).setDeviceOwner(PolicyController.admin(c));Settings.Global.putInt(c.getContentResolver(),Settings.Global.BOOT_COUNT,1);UpdateGate.begin(c,9999);assertTrue(UpdateGate.active(c));long until=c.getSharedPreferences("loop.updates",0).getLong("gate_until",0);CheckoutAccess.begin();try{assertFalse(UpdateGate.active(c));}finally{CheckoutAccess.end();}assertTrue(UpdateGate.active(c));SystemClock.sleep(9*60000);UpdateGate.begin(c,9999);assertEquals(until,c.getSharedPreferences("loop.updates",0).getLong("gate_until",0));SystemClock.sleep(61000);assertFalse(UpdateGate.active(c));}
 @Test public void updateCannotRestrictUnmanagedPhoneOrSurviveBootOrInstalledVersion(){Context c=RuntimeEnvironment.getApplication();UpdateGate.begin(c,9999);assertFalse(UpdateGate.active(c));Shadows.shadowOf(c.getSystemService(DevicePolicyManager.class)).setDeviceOwner(PolicyController.admin(c));Settings.Global.putInt(c.getContentResolver(),Settings.Global.BOOT_COUNT,1);UpdateGate.begin(c,9999);assertTrue(UpdateGate.active(c));Settings.Global.putInt(c.getContentResolver(),Settings.Global.BOOT_COUNT,2);assertFalse(UpdateGate.active(c));UpdateGate.clear(c);UpdateGate.begin(c,BuildConfig.VERSION_CODE);assertFalse(UpdateGate.active(c));}
}
